74	/// One whole-project request to the checker: the components to answer for, and how to reach `tsc`. Built with
75	/// [`SemanticRequest::new`] and answered by [`resolve`].
76	#[derive(Debug, Clone)]
77	pub struct SemanticRequest {
78	    /// Where `tsc` finds `node_modules`; its `--cwd`, and where the search for `typescript` starts.
79	    pub project_root: Utf8PathBuf,
80	    /// A tsconfig whose compiler options the checker uses (read with `parseConfigFile`); with none, a default set.
81	    pub tsconfig: Option<Utf8PathBuf>,
82	    /// An explicit `tsc` binary, instead of `node_modules/typescript/bin/tsc` above `project_root`.
83	    pub tsc_path: Option<Utf8PathBuf>,
84	    /// The components to ask about.
85	    pub targets: Vec<Target>,
86	    /// Bound on each request, and on the `tsc` start-up handshake.
87	    pub request_timeout: Duration,
88	    /// The `typescript` versions the checker may report; one that is not among them is a start-up failure.
89	    pub expected_versions: &'static [&'static str],
90	    /// Write every request and its answer here as JSON, to refresh the replay fixture the tests use.
91	    pub record_to: Option<Utf8PathBuf>,
92	    /// Environment for the `tsc` process; the tests use it to pick a replay scenario.
93	    pub extra_env: Vec<(String, String)>,
94	    /// Ask the checker about a component's props, and about the members of each type, last to first. The answer must
95	    /// not change: no id the checker hands out, and so no order of queries, may show in it. The tests set this.
96	    pub reverse_queries: bool,
97	    /// Compiler options of a `tsc` session that is already initialized. A warm checker sets this once so a request
98	    /// only builds its program.
99	    pub(crate) prepared_options: Option<serde_json::Value>,
100	}
