102	impl SemanticRequest {
103	    /// A request for `targets` under `project_root`, with a 60 second timeout, the supported versions, and no
104	    /// tsconfig or explicit `tsc` path.
105	    pub fn new(project_root: Utf8PathBuf, targets: Vec<Target>) -> Self {
106	        Self {
107	            project_root,
108	            tsconfig: None,
109	            tsc_path: None,
110	            targets,
111	            request_timeout: Duration::from_secs(60),
112	            expected_versions: SUPPORTED_VERSIONS,
113	            record_to: None,
114	            extra_env: Vec::new(),
115	            reverse_queries: false,
116	            prepared_options: None,
117	        }
