18	/// The type of a name the checker could not resolve (an import that does not resolve, a name declared nowhere), which
19	/// the checker answers with its error type: an `any` that is not a written `any`. It is `opaque` with the reason
20	/// `unresolvableImport`, so the prop carries `degradedBy`, and `written` is the name as the source writes it, which is
21	/// also what the reason names (the checker does not say which module specifier was behind it).
22	pub fn unresolved_type(written: impl Into<String>) -> PropType {
23	    let written = written.into();
24	    OpaqueDetail::new(written.clone(), OpaqueReason::UnresolvableImport { specifier: written })
25	}
26	
27	/// A type the checker holds that PropType has no shape for: a conditional or indexed access type it could not resolve
28	/// (its parameters are still open), `keyof T`. It is `opaque` with `reason`, so the prop carries `degradedBy`, and
29	/// `raw` is how the checker prints it.
30	pub fn degraded_type(raw: impl Into<String>, reason: OpaqueReason) -> PropType {
31	    OpaqueDetail::new(raw, reason)
32	}
