61	/// Shares identical props between components, as the structural resolver does: a design system's components repeat
62	/// the same few hundred props, and Chakra's 600 components would otherwise hold 470,000 copies.
63	#[derive(Debug, Default)]
64	pub struct PropInterner {
65	    by_hash: Mutex<FxHashMap<u64, Vec<Arc<SemanticProp>>>>,
66	}
67	
68	impl PropInterner {
69	    /// The one shared copy of `prop`: an equal prop interned earlier, or `prop` itself the first time. If the internal
70	    /// lock is poisoned it returns `prop` unshared rather than failing.
71	    pub fn share(&self, prop: SemanticProp) -> Arc<SemanticProp> {
72	        let hash = prop.structural_hash();
73	        let Ok(mut by_hash) = self.by_hash.lock() else { return Arc::new(prop) };
74	        let bucket = by_hash.entry(hash).or_default();
75	        if let Some(existing) = bucket.iter().find(|existing| ***existing == prop) {
76	            return existing.clone();
77	        }
78	        let shared = Arc::new(prop);
79	        bucket.push(shared.clone());
80	        shared
81	    }
82	}
