137	/// A checker that answers for components as they are asked about, for a long-lived session.
138	///
139	/// `request` never blocks: it queues the targets and returns the receiver that yields the outcome once the checker
140	/// has it, so a caller can wait a bounded time and take the structural answer when the checker is slower.
141	pub trait SemanticProvider: Send + Sync {
142	    /// Queues `targets` for the checker and returns at once with the receiver that will yield their
143	    /// [`SemanticOutcome`].
144	    fn request(&self, targets: Vec<SemanticTarget>) -> std::sync::mpsc::Receiver<SemanticOutcome>;
145	}
