162	/// Replaces `entry`'s props with the checker's, keeping what only the structural pass has (a default value, tags,
163	/// `parent`, `declarations`, and a description when the checker has none). `shared` interns identical props across
164	/// the components of one merge.
165	pub fn apply_semantic_props(
166	    entry: &mut ComponentEntry,
167	    semantic: &SemanticComponent,
168	    shared: &mut FxHashMap<u64, Vec<Arc<ParsedProp>>>,
169	) {
170	    // The whole-project merge replaces the props and leaves `@types/react`'s to the inheritance layers.
171	    replace_props(entry, semantic.props.iter().filter(|prop| !prop.react_declared), Unanswered::Drop, shared);
172	}
