174	/// Merges the checker's `props` into `entry` by name: the checker's type, optionality and description win where both
175	/// have a prop, and every structural prop the checker did not return stays as the structural pass resolved it. Returns
176	/// how many were kept.
177	pub fn merge_semantic_props<'a>(
178	    entry: &mut ComponentEntry,
179	    props: impl Iterator<Item = &'a Arc<SemanticProp>>,
180	    shared: &mut FxHashMap<u64, Vec<Arc<ParsedProp>>>,
181	) -> usize {
182	    replace_props(entry, props, Unanswered::Keep, shared)
183	}
184	
185	/// What a merge does with a structural prop the checker did not return.
186	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
187	enum Unanswered {
188	    /// The checker decides which props exist, as in the whole-project merge: the structural prop is dropped.
189	    Drop,
190	    /// The checker's props are merged by name, as in a session's merge: the structural prop stays as resolved.
191	    Keep,
192	}
193	
194	fn replace_props<'a>(
195	    entry: &mut ComponentEntry,
196	    props_in: impl Iterator<Item = &'a Arc<SemanticProp>>,
197	    unanswered: Unanswered,
198	    shared: &mut FxHashMap<u64, Vec<Arc<ParsedProp>>>,
199	) -> usize {
200	    let mut props: BTreeMap<String, Arc<ParsedProp>> = BTreeMap::new();
201	    for prop in props_in {
202	        let structural = entry.props.get(&prop.name);
203	        let description = if prop.description.is_empty() {
204	            structural.map(|s| s.description.clone()).unwrap_or_default()
205	        } else {
206	            prop.description.clone()
207	        };
208	        // The checker sorts a union's members; where the structural pass resolved the same union, its order is the
209	        // declared one.
210	        let prop_type = match structural {
211	            Some(structural) => order::in_declared_order(prop.prop_type.clone(), &structural.prop_type),
212	            None => prop.prop_type.clone(),
213	        };
214	        let merged = ParsedProp::new(
215	            prop.name.clone(),
216	            prop_type,
217	            prop.required,
218	            structural.and_then(|s| s.default_value.clone()),
219	            description,
220	            structural.map(|s| s.tags.clone()).unwrap_or_default(),
221	            structural.and_then(|s| s.parent.clone()),
222	            structural.map(|s| s.declarations.clone()).unwrap_or_default(),
223	        );
224	        let mut hasher = FxHasher::default();
225	        merged.structural_hash(&mut hasher);
226	        let bucket = shared.entry(hasher.finish()).or_default();
227	        let merged = match bucket.iter().find(|existing| ***existing == merged) {
228	            Some(existing) => existing.clone(),
229	            None => {
230	                let merged = Arc::new(merged);
231	                bucket.push(merged.clone());
232	                merged
233	            }
234	        };
235	        props.insert(prop.name.clone(), merged);
236	    }
237	    let mut kept = 0;
238	    if unanswered == Unanswered::Keep {
239	        for (name, structural) in &entry.props {
240	            if !props.contains_key(name) {
241	                props.insert(name.clone(), structural.clone());
242	                kept += 1;
243	            }
244	        }
245	    }
246	    entry.props = props;
247	    kept
248	}
249	
250	/// Merge the checker's props over `output`, component by component.
251	///
252	/// Per `docs/type-checker-integration.md`: the checker decides which props exist, their types and whether they are
253	/// required; a description comes from the checker, else the structural pass; a default value stays structural (the
254	/// checker has no initializer for a destructured parameter); `parent` and `declarations` stay with the structural
255	/// prop of the same name. Inheritance layers and curated inherited props stay structural. Components the checker did
256	/// not answer for keep their structural result untouched.
257	///
258	/// Records provenance as `Info` diagnostics whose `affects` lists the output keys, so the canonical JSON gains no
259	/// field: one for the components the checker resolved, one per fallback reason.
260	pub fn merge_semantic(output: &mut ExtractionOutput, outcome: SemanticOutcome) {
261	    let SemanticOutcome { components, fallbacks, diagnostics } = outcome;
262	    let mut merged_keys = Vec::new();
263	    let mut shared: FxHashMap<u64, Vec<Arc<ParsedProp>>> = FxHashMap::default();
264	    for semantic in components {
265	        let Some((key, entry)) = output
266	            .components
267	            .iter_mut()
268	            .find(|(_, entry)| entry.file_path == semantic.file_path && entry.display_name == semantic.display_name)
269	        else {
270	            continue;
271	        };
272	        apply_semantic_props(entry, &semantic, &mut shared);
273	        merged_keys.push(key.clone());
274	    }
275	    output.diagnostics.extend(diagnostics);
276	
277	    // A structural diagnostic about a prop the checker now answers for would be stale; the resolved component keeps
278	    // none of its degrade diagnostics.
279	    if !merged_keys.is_empty() {
280	        output.diagnostics.retain(|diagnostic| {
281	            let degrade = matches!(
282	                diagnostic.code,
283	                DiagnosticCode::OpaqueType | DiagnosticCode::MaxDepthExceeded | DiagnosticCode::CircularReference
284	            );
285	            !(degrade
286	                && !diagnostic.affects.is_empty()
287	                && diagnostic.affects.iter().all(|key| merged_keys.contains(key)))
288	        });
289	        merged_keys.sort();
290	        let mut provenance = Diagnostic::new(
291	            DiagnosticSeverity::Info,
292	            DiagnosticCode::SemanticBackend,
293	            format!("{} component(s) resolved by the TypeScript checker", merged_keys.len()),
294	        );
295	        provenance.affects = merged_keys;
296	        output.diagnostics.push(provenance);
297	    }
298	
299	    let mut by_reason: BTreeMap<String, Vec<String>> = BTreeMap::new();
300	    for fallback in fallbacks {
301	        let Some((key, _)) = output
302	            .components
303	            .iter()
304	            .find(|(_, entry)| entry.file_path == fallback.file_path && entry.display_name == fallback.display_name)
305	        else {
306	            continue;
307	        };
308	        by_reason.entry(fallback.reason).or_default().push(key.clone());
309	    }
310	    for (reason, mut keys) in by_reason {
311	        keys.sort();
312	        let mut diagnostic = Diagnostic::new(
313	            DiagnosticSeverity::Info,
314	            DiagnosticCode::SemanticBackend,
315	            format!("{} component(s) kept their structural result: {reason}", keys.len()),
316	        );
317	        diagnostic.affects = keys;
318	        output.diagnostics.push(diagnostic);
319	    }
320	}
