// The construct suite through the checker path (ADR 0026): `caliper-docgen extract --experimental-semantic-types` with a
// `tsrs` binary over apps/oracle/construct-suite, and each row's verdict against its golden. It is a gate on
// construct-suite/checker-expectations.json: it prints the report, then exits 1 when a row is better or worse than the
// expectation allows (an improvement means the gap closed: update the file), when the checker did not answer for a row,
// or when the checker backend was unavailable. Run it with `just test-checker-lane`, or by hand:
//
//   cargo build --release -p caliper-docgen
//   CALIPER_SEMANTIC=1 TSRS_BIN=<node_modules/@tsrs/<platform>/tsrs> pnpm --filter caliper-docgen-oracle construct:checker
//
// A row the checker did not answer for (it kept the structural result) is listed apart: its verdict says nothing about
// the checker. `--json <file>` also writes every row with the type each side gave.
import { existsSync, writeFileSync } from 'node:fs'
import { join, resolve } from 'node:path'
import { checkerExpectations, laneFailures, runCheckerLane, type Row } from './construct-checker-run.ts'
import { GREEN } from './construct-suite.ts'

if (process.env.CALIPER_SEMANTIC !== '1') {
  console.error('construct-checker-lane: set CALIPER_SEMANTIC=1 (and TSRS_BIN) to run the suite through the checker.')
  process.exit(2)
}
const tsrs = process.env.TSRS_BIN
if (!tsrs || !existsSync(tsrs)) {
  console.error(`construct-checker-lane: TSRS_BIN must name a tsrs binary (got ${JSON.stringify(tsrs)}).`)
  process.exit(2)
}
const bin = resolve(
  process.env.CALIPER_BIN ?? join(import.meta.dirname, '..', '..', '..', 'target', 'release', 'caliper-docgen'),
)
if (!existsSync(bin)) {
  console.error(`construct-checker-lane: no caliper binary at ${bin}; build one or set CALIPER_BIN.`)
  process.exit(2)
}
const jsonOut = process.argv.includes('--json') ? process.argv[process.argv.indexOf('--json') + 1] : undefined

const run = runCheckerLane(bin, tsrs)
if (run.backendProblem !== undefined) {
  console.error(`construct-checker-lane: the checker was unavailable: ${run.backendProblem}`)
  process.exit(1)
}
const { elapsedMs, rows } = run

const checkerRows = rows.filter((row) => row.answered)
const structuralRows = rows.filter((row) => !row.answered)
const green = (row: Row) => GREEN.includes(row.verdict)
console.log(
  `checker path over ${rows.length} rows in ${elapsedMs} ms: ${checkerRows.length} answered by the checker, ${structuralRows.length} kept their structural result`,
)
const count = (list: Row[]) => {
  const tally = new Map<string, number>()
  for (const row of list) tally.set(row.verdict, (tally.get(row.verdict) ?? 0) + 1)
  return [...tally].map(([verdict, n]) => `${verdict} ${n}`).join(', ')
}
console.log(`  checker rows: ${count(checkerRows)}`)
console.log('')
console.log('Rows the checker answered that are not identical or spelled (verdict | structural expectation | golden):')
for (const row of checkerRows.filter((r) => !green(r))) {
  console.log(`  ${row.id}: ${row.verdict} | ${row.structural.join('/')} | ${row.golden}`)
}
console.log('')
console.log('Rows the checker answered that the structural result did not get green (improvements):')
for (const row of checkerRows.filter((r) => green(r) && !r.structural.every((v) => GREEN.includes(v)))) {
  console.log(`  ${row.id}: ${row.verdict} (structural: ${row.structural.join('/')})`)
}
console.log('')
console.log('Rows that kept their structural result (no checker verdict):')
for (const row of structuralRows) console.log(`  ${row.id}: ${row.verdict}`)

if (jsonOut) writeFileSync(jsonOut, JSON.stringify({ elapsedMs, rows }, null, 2))

const failures = laneFailures(run, checkerExpectations())
if (failures.length > 0) {
  console.error('')
  console.error(`construct-checker-lane: ${failures.length} row(s) differ from checker-expectations.json:`)
  for (const failure of failures) console.error(`  ${failure}`)
  process.exit(1)
}
console.log('')
console.log('every row matches checker-expectations.json')
// One run of the construct suite through the checker path (ADR 0026), shared by the lane script
// (src/construct-checker-lane.ts) and its test (tests/construct-checker-lane.test.ts): `caliper-docgen extract
// --experimental-semantic-types` with a `tsrs` binary over apps/oracle/construct-suite, and each row's verdict against
// its golden and against checker-expectations.json.
import { execFileSync } from 'node:child_process'
import { readFileSync, realpathSync } from 'node:fs'
import { join } from 'node:path'
import { checkCaliperShape, flattenProps } from './caliper-input.ts'
import {
  expectationFailure,
  expectationProblems,
  listFixtures,
  PROP,
  rowVerdict,
  type Expectation,
  type Golden,
  type RowVerdict,
} from './construct-suite.ts'

export const suiteDir = realpathSync(join(import.meta.dirname, '..', 'construct-suite'))

export interface Row {
  id: string
  verdict: RowVerdict
  /** The structural path's allowed verdicts (expectations.json), for the improvements listing. */
  structural: RowVerdict[]
  /** The checker answered for this row; false means it kept its structural result, so the verdict says nothing about the checker. */
  answered: boolean
  type: unknown
  degradedBy: unknown
  golden: string
}

export interface LaneRun {
  elapsedMs: number
  rows: Row[]
  /** A message when the checker backend was unavailable, in which case no row is meaningful. */
  backendProblem?: string
}

interface Expectations {
  rows: Record<string, Expectation>
}

function readExpectations(name: string): Expectations {
  return JSON.parse(readFileSync(join(suiteDir, name), 'utf8'))
}

export const structuralExpectations = (): Expectations => readExpectations('expectations.json')
export const checkerExpectations = (): Expectations => readExpectations('checker-expectations.json')

function extract(bin: string, extra: string[]): any {
  const stdout = execFileSync(
    bin,
    [
      'extract',
      '--src',
      suiteDir,
      '--json',
      '--html-attributes',
      'full',
      '--include-unexported',
      '--load-dependencies',
      '--collapse-inherited-props',
      'none',
      '--no-cache',
      '--quiet',
      ...extra,
    ],
    { encoding: 'utf8', maxBuffer: 512 * 1024 * 1024 },
  )
  const caliper = JSON.parse(stdout)
  checkCaliperShape(caliper)
  return caliper
}

/** Run the suite through the checker path and give every row its verdict. */
export function runCheckerLane(bin: string, tsrs: string): LaneRun {
  const started = performance.now()
  const checked = extract(bin, ['--experimental-semantic-types', '--tsc-path', tsrs])
  const elapsedMs = Math.round(performance.now() - started)

  const backendProblem = (checked.diagnostics ?? []).find((d: any) =>
    String(d.message).includes('checker backend unavailable'),
  )?.message

  /** The component keys the checker answered for, from the provenance diagnostic the merge writes. */
  const answered = new Set<string>()
  for (const diagnostic of checked.diagnostics ?? []) {
    if (String(diagnostic.message).includes('resolved by the TypeScript checker')) {
      // `affects` is a list of component keys, or the id of one in `nameLists` (the canonical JSON shares repeated lists).
      const affects =
        typeof diagnostic.affects === 'string' ? checked.nameLists[diagnostic.affects] : diagnostic.affects
      for (const key of affects ?? []) answered.add(key)
    }
  }

  const byFile = new Map<string, { key: string; prop: any }>()
  for (const [key, component] of Object.entries<any>(checked.components)) {
    if (component.displayName !== 'Row') continue
    const id = flattenProps(checked, key, component)[PROP]
    byFile.set(realpathSync(component.filePath), { key, prop: id === undefined ? undefined : checked.props[id] })
  }

  const structural = structuralExpectations().rows
  const rows: Row[] = []
  for (const fixture of listFixtures(suiteDir)) {
    const golden: Golden = JSON.parse(readFileSync(fixture.golden, 'utf8'))
    const found = byFile.get(realpathSync(fixture.file))
    rows.push({
      id: fixture.id,
      verdict: rowVerdict(found?.prop, golden),
      structural: structural[fixture.id]?.verdicts ?? [],
      answered: found !== undefined && answered.has(found.key),
      type: found?.prop?.type,
      degradedBy: found?.prop?.degradedBy,
      golden: golden.text,
    })
  }
  return { elapsedMs, rows, backendProblem }
}

/** What is wrong with the run against checker-expectations.json: rows the checker did not answer for, rows better or
 * worse than allowed, and expectations that do not match the fixtures. Empty when the lane holds. */
export function laneFailures(run: LaneRun, expectations: Expectations): string[] {
  const failures = expectationProblems(
    run.rows.map((row) => row.id),
    expectations.rows,
  )
  for (const row of run.rows) {
    if (!row.answered) failures.push(`${row.id}: the checker did not answer for this row (kept the structural result)`)
    const expectation = expectations.rows[row.id]
    const failure = expectation && expectationFailure(row.id, row.verdict, expectation)
    if (failure) failures.push(failure)
  }
  return failures
}
// The construct suite through the checker path (ADR 0026; construct-suite/README.md "The checker lane"): every row's
// verdict held to checker-expectations.json, so a row that regresses fails and a row that improves fails until the
// expectation is updated. The live run needs Caliper's release binary and the pinned tsrs; without them it skips with a
// warning, and REQUIRE_CALIPER_BIN=1 / REQUIRE_TSRS=1 turn each skip into a failure.
import { existsSync } from 'node:fs'
import { join, resolve } from 'node:path'
import { describe, expect, it } from 'vitest'
import {
  checkerExpectations,
  laneFailures,
  runCheckerLane,
  structuralExpectations,
  type LaneRun,
} from '../src/construct-checker-run.ts'
import { expectationProblems } from '../src/construct-suite.ts'
import { resolveTsrsBin } from '../src/tsrs-bin.ts'

const bin = resolve(
  process.env.CALIPER_BIN ?? join(import.meta.dirname, '..', '..', '..', 'target', 'release', 'caliper-docgen'),
)
const binAvailable = existsSync(bin)
let tsrs: string | undefined
let tsrsProblem = ''
try {
  tsrs = await resolveTsrsBin()
  if (!existsSync(tsrs)) {
    tsrsProblem = `no tsrs binary at ${tsrs}`
    tsrs = undefined
  }
} catch (error) {
  tsrsProblem = error instanceof Error ? error.message : String(error)
}
if (!binAvailable) console.warn(`checker lane skipped: no caliper binary at ${bin}. Set REQUIRE_CALIPER_BIN=1 to fail.`)
if (tsrs === undefined) console.warn(`checker lane skipped: ${tsrsProblem}. Set REQUIRE_TSRS=1 to fail.`)

const row = (id: string, verdict: LaneRun['rows'][number]['verdict'], answered = true): LaneRun['rows'][number] => ({
  id,
  verdict,
  structural: [],
  answered,
  type: undefined,
  degradedBy: undefined,
  golden: '',
})

describe('the checker lane expectations', () => {
  it('cover exactly the rows of the structural expectations, and every gap has a reason', () => {
    expect.hasAssertions()
    const ids = Object.keys(structuralExpectations().rows)
    expect(expectationProblems(ids, checkerExpectations().rows)).toStrictEqual([])
  })

  it('fail a run with a row better or worse than allowed, or one the checker did not answer for', () => {
    expect.hasAssertions()
    const rows = {
      'a/01-green': { verdicts: ['identical', 'spelled'] },
      'a/02-gap': { verdicts: ['less precise'], gap: 'unevaluated' },
      'a/03-green': { verdicts: ['identical', 'spelled'] },
    } satisfies Parameters<typeof laneFailures>[1]['rows']
    const ok: LaneRun = {
      elapsedMs: 0,
      rows: [row('a/01-green', 'spelled'), row('a/02-gap', 'less precise'), row('a/03-green', 'identical')],
    }
    expect(laneFailures(ok, { rows })).toStrictEqual([])
    const moved: LaneRun = {
      elapsedMs: 0,
      rows: [row('a/01-green', 'wrong'), row('a/02-gap', 'identical'), row('a/03-green', 'identical', false)],
    }
    const failures = laneFailures(moved, { rows })
    expect(failures).toHaveLength(3)
    expect(failures.join('\n')).toContain('a/01-green: wrong (worse than expected')
    expect(failures.join('\n')).toContain('a/02-gap: identical (better than expected')
    expect(failures.join('\n')).toContain('a/03-green: the checker did not answer')
  })
})

describe('the live checker lane', () => {
  it.runIf(process.env.REQUIRE_CALIPER_BIN === '1')('has the caliper binary when REQUIRE_CALIPER_BIN=1', () => {
    expect(binAvailable ? 'present' : `REQUIRE_CALIPER_BIN=1 but there is no caliper binary at ${bin}`).toBe('present')
  })

  it.runIf(process.env.REQUIRE_TSRS === '1')('has the tsrs binary when REQUIRE_TSRS=1', () => {
    expect(tsrs === undefined ? `REQUIRE_TSRS=1 but ${tsrsProblem}` : 'present').toBe('present')
  })

  it.skipIf(!binAvailable || tsrs === undefined)('gives every row the verdict checker-expectations.json allows', () => {
    expect.hasAssertions()
    const run = runCheckerLane(bin, tsrs!)
    expect(run.backendProblem).toBeUndefined()
    expect(run.rows.length).toBeGreaterThan(0)
    expect(laneFailures(run, checkerExpectations())).toStrictEqual([])
  })
})

