/// The own types of a component's props, from the top. Up to [`ROOTS_IN_FLIGHT`] are converted at once, so the
/// checker is not left idle between the round trips of one conversion: a design system's component has hundreds of
/// props and a conversion is thousands of small requests (Chakra's `Button`: 4,400). Each conversion depends only
/// on its type (see the module docs), so the answer does not depend on which finishes first; with `reverse` they
/// run one at a time, last to first, as the test that holds the answer to that asks.
pub(crate) async fn convert_roots(&self, infos: &[TypeInfo]) -> Result<Vec<PropType>, CallError> {
    if self.reverse || infos.len() < 2 {
        return self.convert_all(infos, &Cx::default()).await;
    }
    let limit = Arc::new(tokio::sync::Semaphore::new(ROOTS_IN_FLIGHT));
    let mut tasks = tokio::task::JoinSet::new();
    for (index, info) in infos.iter().enumerate() {
        let (converter, info, limit) = (self.clone(), info.clone(), limit.clone());
        tasks.spawn(async move {
            let _permit = limit.acquire_owned().await;
            (index, converter.convert(&info, &Cx::default()).await)
        });
    }
    let mut slots: Vec<Option<PropType>> = vec![None; infos.len()];
    while let Some(joined) = tasks.join_next().await {
        let (index, converted) = match joined {
            Ok(done) => done,
            Err(error) => {
                tasks.abort_all();
                return Err(CallError::Fatal(format!("a prop's conversion stopped: {error}")));
            }
        };
        match converted {
            Ok(converted) => {
                if let Some(slot) = slots.get_mut(index) {
                    *slot = Some(converted);
                }
            }
            Err(error) => {
                tasks.abort_all();
                return Err(error);
            }
        }
    }
    Ok(slots.into_iter().flatten().collect())
}

