644	    /// The one gate every descent into the parts of a type passes, before the parts are converted. It stops, in this
645	    /// order, a type that is an instantiation already being expanded around it (a back-reference to its declaration,
646	    /// whose arguments are the instantiation's), a type past [`MAX_DEPTH`], and a type whose `measure`d parts exceed the
647	    /// `limits`. `measure` fetches the parts and says how many there are; it is not called for a type stopped before.
648	    /// Otherwise the parts come back with the context to convert them in.
649	    async fn enter<T, F, Fut>(
650	        &self,
651	        info: &TypeInfo,
652	        origin: Option<&Origin>,
653	        cx: &Cx,
654	        limits: [usize; 2],
655	        measure: F,
656	    ) -> Result<Gate<T>, CallError>
657	    where
658	        T: Send,
659	        F: FnOnce() -> Fut + Send,
660	        Fut: Future<Output = Result<(T, usize), CallError>> + Send,
661	    {
662	        // The handle is the instantiation: `Box<string>` inside `Box<Box<string>>` is another type from the one around it.
663	        if let Some(origin) = origin
664	            && cx.encloses(info.id)
665	        {
666	            return Ok(Gate::Stop(self.recursive(info, origin, cx).await?));
667	        }
668	        if cx.depth >= MAX_DEPTH {
669	            return Ok(Gate::Stop(self.truncated(info, origin, TruncationLimit::Depth).await?));
670	        }
671	        let (parts, total) = measure().await?;
672	        if total > cx.limit(limits) {
673	            let limit = TruncationLimit::Members { total: to_u32(total) };
674	            return Ok(Gate::Stop(self.truncated(info, origin, limit).await?));
675	        }
676	        Ok(Gate::Open { parts, inner: cx.below(origin.map(|_| info.id)) })
677	    }
