679	    async fn union(&self, info: &TypeInfo, cx: &Cx) -> Result<PropType, CallError> {
680	        let origin = self.origin(info).await?;
681	        if let Some(terminal) = origin.as_ref().and_then(Origin::react_terminal) {
682	            return Ok(terminal);
683	        }
684	        // The width is checked below, after React's aliases flattened into the union are recognized: they are wide.
685	        let gate = self.enter(info, origin.as_ref(), cx, [usize::MAX; 2], || self.members_of(info)).await?;
686	        let (members, inner) = match gate {
687	            Gate::Stop(stopped) => return Ok(stopped),
688	            Gate::Open { parts, inner } => (parts, inner),
689	        };
690	        // `ReactNode | (() => void)` arrives with the alias flattened into its members: they are the terminal again.
691	        let over = members.len() > cx.limit(MAX_MEMBERS);
692	        let Some((terminal, absorbed)) = self.react_alias_members(&members, over).await? else {
693	            if over {
694	                let limit = TruncationLimit::Members { total: to_u32(members.len()) };
695	                return self.truncated(info, origin.as_ref(), limit).await;
696	            }
697	            return Ok(union_of(self.convert_all(&members, &inner).await?));
698	        };
699	        let kept: Vec<TypeInfo> = members
700	            .iter()
701	            .zip(&absorbed)
702	            .filter(|(_, absorbed)| !**absorbed)
703	            .map(|(member, _)| member.clone())
704	            .collect();
705	        if kept.len() + 1 > cx.limit(MAX_MEMBERS) {
706	            let limit = TruncationLimit::Members { total: to_u32(kept.len() + 1) };
707	            return self.truncated(info, origin.as_ref(), limit).await;
708	        }
709	        let mut converted = self.convert_all(&kept, &inner).await?;
710	        let first = absorbed.iter().position(|absorbed| *absorbed).unwrap_or_default();
711	        let before = absorbed.iter().take(first).filter(|absorbed| !**absorbed).count();
712	        converted.insert(before, terminal);
713	        Ok(union_of(converted))
714	    }
