738	    /// that [`is_tag`] is taken: any other string literal is an alternative the author wrote beside `ElementType`, and
739	    /// the terminal does not stand for it.
740	    async fn element_type_members(&self, members: &[TypeInfo]) -> Result<Option<Vec<bool>>, CallError> {
741	        let tags = members.iter().filter(|member| is_tag(member)).count();
