/// Asks `method` about every type of `ids` not already known, in one round trip, so that the [`Rpc::about_type`]
/// calls a conversion makes next are answered here.
pub(crate) async fn prefetch(&self, method: &'static str, param: &'static str, ids: &[u64]) -> Result<(), CallError> {
    let wanted: Vec<u64> = match self.known.lock() {
        Ok(known) => {
            let mut wanted: Vec<u64> = ids.iter().copied().filter(|id| !known.contains_key(&(method, *id))).collect();
            wanted.sort_unstable();
            wanted.dedup();
            wanted
        }
        Err(_) => return Ok(()),
    };
    if wanted.is_empty() {
        return Ok(());
    }
    let answers = self.batch(wanted.iter().map(|id| (method, json!({ param: id }))).collect()).await?;
    if let Ok(mut known) = self.known.lock() {
        for (id, answer) in wanted.into_iter().zip(answers) {
            known.insert((method, id), answer);
        }
    }
    Ok(())
}

