/// Each symbol's documentation comment, empty where it has none, in one round trip: a design system's component has
/// hundreds of props, and a round trip each was most of its first answer.
pub(crate) async fn documentations(&self, symbols: &[&Value]) -> Result<Vec<String>, CallError> {
    if symbols.is_empty() {
        return Ok(Vec::new());
    }
    let requests = symbols.iter().map(|symbol| ("getDocumentationComment", json!({ "symbol": symbol }))).collect();
    self.batch(requests).await?.into_iter().map(decode).collect()
}

